antiPatterns.example:
// Avoid: bordered input inside a bordered group
<InputGroup><Input className="border" /></InputGroup>

// Prefer: let InputGroup strip the chrome
<InputGroup><Input /></InputGroup>

// Avoid
<InputGroupAddon side="right"><button>×</button></InputGroupAddon>

// Prefer
<InputGroupAddon side="right">
  <Button aria-label="Clear input" variant="ghost">×</Button>
</InputGroupAddon>
